function Invoke-RemoteReboot {
    param (
        [string]$ComputerName,
        [PSCredential]$Credential = $null
    )

    try {
        # Reboot the remote computer using WMI
        if ($Credential) {
            Invoke-WmiMethod -Class Win32_OperatingSystem -Method Reboot -ComputerName $ComputerName -Credential $Credential
        } else {
            Invoke-WmiMethod -Class Win32_OperatingSystem -Method Reboot -ComputerName $ComputerName
        }
        Write-Output 'Remote reboot initiated successfully.'
    } catch {
        Write-Error "Failed to reboot remote computer: $_.Exception.Message"
    }
}

# Example usage:
# Invoke-RemoteReboot -ComputerName 'remotehost' -Credential (Get-Credential)

