# Script: Invoke-RemoteReboot.ps1
# Description: Reboots a remote computer using WS-Man protocol

param(
    [string]$ComputerName = "REMOTE_HOST",
    [PSCredential]$Credential = $null,
    [switch]$EnablePSRemoting = $false
)

# If no credentials provided, prompt for them
If ($Credential -eq $null) {
    $Credential = Get-Credential -Message "Enter Administrator credentials on $ComputerName"
}

# Check if PSRemoting is enabled on the remote machine
Try {
    # Test if we can reach the remote machine
    If ((Test-Connection -ComputerName $ComputerName -Count 1 -ErrorAction SilentlyContinue) -eq $false) {
        Write-Error "Remote machine $ComputerName is not reachable."
        Exit
    }

    # Check if WinRM service is running
    $winrmStatus = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        Get-Service WinRM | Select-Object -ExpandProperty Status
    } -ErrorAction SilentlyContinue

    If ($EnablePSRemoting) {
        # Enable PSRemoting if not already enabled
        If ($winrmStatus -ne "Running") {
            Write-Host "Enabling WS-Man/PSRemoting on $ComputerName..."
            Invoke-Command -ComputerName $ComputerName -ScriptBlock {
                Start-Service WinRM
                Set-Item WSMan:\localhost\EnableNetworkAccess "True"
                Restart-Service WinRM
            } -Credential $Credential
            Start-Sleep -Seconds 15 # Wait for services to start
        }
    } Else {
        If ($winrmStatus -ne "Running") {
            Write-Error "WS-Man/PSRemoting is not enabled on $ComputerName. Use -EnablePSRemoting to enable it."
            Exit
        }
    }

    # Execute the reboot
    Write-Host "Initiating reboot of $ComputerName..."
    Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        Restart-Computer -Force
    } -Credential $Credential

    Write-Host "Reboot initiated successfully."

} Catch {
    Write-Error "Failed to reboot $ComputerName: $_"
}
