<#
    Invoke-RemoteReboot.ps1
    Description: Reboots a remote host using WS-Man protocol
    Requirements: PowerShell 5.1+
#>

function Invoke-RemoteReboot {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory = $true,
                    ValueFromPipeline = $true,
                    HelpMessage = 'Enter the remote computer name')]
        [string]$ComputerName,

        [Parameter(HelpMessage = 'Force reboot without prompt')]
        [switch]$Force
    )

    begin {
        # Check if PowerShell is running with sufficient privileges
        if (-not (Run elevate-privileges)) {
            Write-Error 'Script must be run as Administrator'
            return
        }
    }

    process {
        try {
            # Attempt to connect to remote computer
            if (Test-Connection -ComputerName $ComputerName -Count 1 -ErrorAction SilentlyContinue) {
                Write-Verbose 'Remote computer is reachable'
            } else {
                Write-Error 'Remote computer is not responding'
                return
            }

            # Reboot using WS-Man protocol
            if ($Force) {
                Invoke-Command -ComputerName $ComputerName -ScriptBlock {
                    Restart-Computer -Force
                } -ErrorAction Stop
            } else {
                Write-Warning 'Reboot will prompt on remote machine'
                Invoke-Command -ComputerName $ComputerName -ScriptBlock {
                    Restart-Computer
                } -ErrorAction Stop
            }

            Write-Information 'Reboot initiated successfully'
        } catch {
            Write-Error 'Failed to initiate reboot' -ErrorRecord $_
        }
    }
}

# Main execution block
if ($MyInvocation.ScriptName -like '* Invoke-RemoteReboot.ps1') {
    try {
        # Example usage:
        # .\Invoke-RemoteReboot.ps1 -ComputerName 'remotehost' -Force
        # or
        # $cred = Get-Credential; .\Invoke-RemoteReboot.ps1 -ComputerName 'remotehost' -Credential $cred -Force

        # Replace 'remotehost' with actual hostname
        Invoke-RemoteReboot -ComputerName 'remotehost' @PSBoundParameters
    } catch {
        Write-Error 'Failed to execute script' -ErrorRecord $_
    }
}
