# Invoke-RemoteReboot.ps1
# Reboots a remote computer using WS-Man protocol

try {
    # Check if WinRM is running on the remote computer
    if ((Test-WSMan -ComputerName $remoteComputer -ErrorAction SilentlyContinue) -eq $false) {
        Write-Warning 'WinRM service is not running on the remote computer or connection failed.'
        exit
    }

    # Get credentials
    $username = Read-Host 'Enter remote computer admin username'
    $password = Read-Host 'Enter remote computer admin password' -AsSecureString
    $cred = New-Object System.Management.Automation.PSCredential ($username, $password)

    # Reboot the remote computer
    Invoke-Command -ComputerName $remoteComputer -Credential $cred -ScriptBlock {
        Restart-Computer -Force
    }

    Write-Host 'Remote computer is being rebooted...' -ForegroundColor Green
} catch {
    Write-Error 'Failed to reboot remote computer.'
    Write-Error $_.Exception.Message
}
